<?php
declare(strict_types=1); if(PHP_SAPI!=='cli'){http_response_code(403);exit("Run with PHP CLI only.\n");}require_once dirname(__DIR__).DIRECTORY_SEPARATOR.'includes'.DIRECTORY_SEPARATOR.'bootstrap.php';$pdo=db_connection();if((int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn()!==0){fwrite(STDERR,"An administrator already exists; setup is closed.\n");exit(1);}fwrite(STDOUT,'Username (3-50 letters, digits, . _ -): ');$u=trim((string)fgets(STDIN));if(!preg_match('/^[A-Za-z0-9_.-]{3,50}$/D',$u)){fwrite(STDERR,"Invalid username.\n");exit(1);}fwrite(STDOUT,'Password (at least 12 characters; terminal input is visible): ');$pw=rtrim((string)fgets(STDIN),"\r\n");if(strlen($pw)<12||strlen($pw)>4096){fwrite(STDERR,"Password must be at least 12 bytes.\n");exit(1);}$s=$pdo->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)');$s->execute([$u,password_hash($pw,PASSWORD_DEFAULT)]);fwrite(STDOUT,"Administrator created. This setup command will refuse further accounts.\n");
